<script lang="ts">
 import {onDestroy,onMount} from 'svelte';import type {GiscusConfig} from '$lib/server/giscus';
 let {config,contentId}:{config:GiscusConfig|null;contentId:string}=$props();let host:HTMLDivElement;let status=$state('idle');let ready=$state(false);onMount(()=>{ready=true;});let timer:ReturnType<typeof setTimeout>|undefined;
 function message(event:MessageEvent){if(event.origin!=='https://giscus.app'||event.source!==host?.querySelector('iframe')?.contentWindow)return;if(event.data?.giscus?.error){status='failed';clearTimeout(timer);}else if(event.data?.giscus?.resizeHeight){status='loaded';clearTimeout(timer);}}
 function load(){if(!config||status==='loading')return;host.replaceChildren();status='loading';const script=document.createElement('script');script.src='https://giscus.app/client.js';script.async=true;script.crossOrigin='anonymous';const values={'repo':config.repo,'repo-id':config.repoId,'category-id':config.categoryId,mapping:'specific',term:contentId,strict:'1','reactions-enabled':'1','emit-metadata':'1','input-position':'top',theme:'preferred_color_scheme',lang:'zh-CN',loading:'lazy'};for(const [k,v]of Object.entries(values))script.setAttribute(`data-${k}`,v);script.onerror=()=>{status='failed';clearTimeout(timer);};host.append(script);window.addEventListener('message',message);timer=setTimeout(()=>{if(status==='loading')status='failed';},15000);}
 onDestroy(()=>{clearTimeout(timer);if(typeof window!=='undefined')window.removeEventListener('message',message);});
</script>
<section><h2>评论</h2>{#if !config}<p class="muted">评论尚未配置。</p>{:else}<p>评论由 GitHub Discussions / Giscus 提供，加载后会连接第三方服务。</p>{#if status==='idle'}<button disabled={!ready} onclick={load}>加载评论</button>{:else if status==='loading'}<p role="status">正在加载评论…</p>{:else if status==='failed'}<p role="alert">评论暂时无法加载。</p><button disabled={!ready} onclick={load}>重试加载评论</button>{/if}{/if}<div bind:this={host}></div></section>
<style>section{margin-top:48px;border-top:1px solid var(--line);padding-top:24px}</style>
